import json,re,pathlib,collections,hashlib
H=pathlib.Path(__file__).resolve().parent
load=lambda p:json.loads((H/p).read_text())
def save(p,d):(H/p).write_text(json.dumps(d,indent=2)+'\n')
def shape(q):
 x=re.search(r'\\begin\{bmatrix\}(.*?)\\end\{bmatrix\}',q[':question/problem'],re.S)[1].split('\\\\');return (len(x),len(x[0].split('&')))
def typ(q):return 'radio' if len(q[':question/answer-fields'])==1 else ('let-dual-blank' if q[':question/problem'].startswith('Let') else 'where-dual-blank')
def pair(a):return tuple(map(int,re.findall(r'\d+',a[':answer/value'])))
probes=[];coverage=[]
for fn in ['samples.json','delivery-sample/accepted.json','runner-batch.json','delivery-batch/accepted.json']:
 records=load(fn);groups={t:[r for r in records if typ(r['question'])==t] for t in ['radio','where-dual-blank','let-dual-blank']}
 coverage.append({'case':fn,'sample_refs':[fn],'result':json.dumps({t:{'n':len(rs),'shapes':dict(collections.Counter(str(shape(r['question'])) for r in rs)),'square':sum(shape(r['question'])[0]==shape(r['question'])[1] for r in rs)} for t,rs in groups.items()})})
 for t,rs in groups.items():
  if not rs:continue
  if t=='radio':
   strategies={'first answer position':lambda b:b[0], 'last answer position':lambda b:b[-1], 'smallest row/column pair':lambda b:min(b,key=pair),'largest row/column pair':lambda b:max(b,key=pair),'first square option (else first)':lambda b:next((a for a in b if len(set(pair(a)))==1),b[0])}
   for cue,strategy in strategies.items():
    wins=sum(pair(strategy(r['question'][':question/answer-fields'][0][':answer-field/choices']))==shape(r['question']) for r in rs)
    probes.append({'cue':cue,'subgroup':f'{fn}: {t}','scope':'within_template','strategy':cue,'correct':wins,'total':len(rs),'baseline':0.2,'disposition':'not_predictive','conclusion':'Uniform choice among five answers has success 0.2. Bank is sampled before a uniform correct role. Finite measurements, particularly one-radio runner subgroup, cannot establish a predictor; controls hold bank fixed and change correct role.','sample_refs':[fn,'counterfactual-records.json']})
  else:
   wins=sum(shape(r['question'])[0]==shape(r['question'])[1] for r in rs)
   probes.append({'cue':t+' wording','subgroup':fn+': '+t,'scope':'within_template','strategy':'Count rows then copy that answer into both blanks.','correct':wins,'total':len(rs),'baseline':0.2,'disposition':'not_predictive','conclusion':'The second dimension is uniform over 2..6 before delivery, so blindly copying a known row count has baseline 0.2. Both rectangular and square cases occur in control/sample domain; singleton delivered subgroups do not prove a reusable cue.','sample_refs':[fn,'counterfactual-records.json']})
 # One literal answer strategy applies across every format.
 wins=sum(shape(r['question'])==(3,3) for r in records)
 probes.append({'cue':'no matrix inspection','subgroup':fn,'scope':'overall','strategy':'Always answer 3 × 3, or fill 3 in both blanks.','correct':wins,'total':len(records),'baseline':0.04,'disposition':'not_predictive','conclusion':'Baseline 1/25 is uniform guessing among ordered supported shapes. The runner batch has five distinct shapes, preventing one literal response from solving it.','sample_refs':[fn]})
# Known current inventory: simulate the engine easy-band conditional draw faithfully.
inv=load('inventory-records.json'); eligible=[q for q in inv if not q.get(':question/retired',False)]
def band(q):
 x=q.get(':question/difficulty');return (x.get(':db/ident') if isinstance(x,dict) else x)
easy=sorted(q[':db/id'] for q in eligible if band(q)==':question.difficulty/easy');unrated=[q[':db/id'] for q in eligible if band(q) is None]
counts=collections.Counter()
for i in range(300):
 d=hashlib.sha256(f'course-academy/question-selection/v1/review-matrix-{i}'.encode()).digest();u=(int.from_bytes(d[8:16],'big')>>11)/(1<<53);counts[easy[int(u*len(easy))]]+=1
save('selection-results.json',{'basis':5665,'rules':['learning.rs validate_practice_question excludes retired, free and multistep questions; captured records have ordinary gradable blank/radio fields and no retirement flag.','learning.rs lesson candidate filter excludes seen records.','question_selection.rs selects a positive rated difficulty band first, then a uniform index from sorted entity IDs; unknown difficulties are fallback only.'],'retired':len(inv)-len(eligible),'easy_ids':easy,'unrated_ids':unrated,'conditional_easy_draws':dict(counts),'seeds':'review-matrix-0 through review-matrix-299','sample_size':300,'prospective_batch':'All 5 accepted generated records are easy; each has the same conditional weight within the easy pool. No shape/label/template filter. Database entity IDs do not yet exist, so future exact draw sequence is not asserted.','limits':['No captured learner history or policy weights: conclusions condition on a positive easy weight and fresh records. Seen records are removed, so later learner-specific finite subsets need not remain balanced.','Captured basis 5665 only; no database access.']})
cf=[]
for kind in ['relevant','irrelevant']:
 cf.append({'kind':kind,'change':'Append [7,8,9] as a third row to a fixed 2 × 3 matrix; radio bank unchanged.' if kind=='relevant' else 'Rename A to Z and change entries to zeros, a negative, a radical and a fraction, keeping 2 × 3 layout.','expected':'Answer changes from 2 × 3 to 3 × 3; first blank changes, second stays 3; old radio answer rejected.' if kind=='relevant' else 'Answer remains 2 × 3 in every template.','observed':'All three templates obey relationship; prompt and solution follow the count. Native grader checks all radio choices and numeric equivalent/wrong entries on both records. Actual UI screenshots checked.','status':'passed','justification':'Source tutorial defines dimensions solely by row and column counts; entry values and labels do not contribute.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-input.json','grader-results.json','render/rendering.json','render-remaining/rendering.json']})
report={'learner_operation':'Count rows and columns in the displayed array and report the ordered pair; do not calculate with entries.','fixed_features':[{'feature':'One numeric matrix, rows before columns, radio or two numeric blanks.','justification':'All nine source questions ask dimensions with these contracts.'},{'feature':'Normal sampled dimensions 2..6 on each axis.','justification':'Conservative practice domain covers all target-KP assessed shapes and adds independent rectangular roles within their visual workload. Later vector tutorial supports a wider optional domain; this generator does not claim full coverage of the whole lesson.'}], 'answer_roles':[{'role':'Ordered row and column counts','eligible_variation':'Both can independently range over supported sizes; blank wording is not a square-only constraint.','observed':'All 25 supported shapes validated in every template; random sample and runner coverage below.'},{'role':'Correct radio choice','eligible_variation':'Any of five supported bank shapes and any position can be correct, independent of label and values.','observed':'Normal sampling chooses bank first then uniform correct shape; controlled pair changes correct member with same bank.'}], 'coverage':coverage+[{'case':'Full supported shape domain across templates','sample_refs':['boundaries.json','finite-batch.json','rejection-results.json'],'result':'75 explicit boundary/domain records: all 25 shapes in all three templates. 25-count batch retains 25 distinct shapes after 70 repeated-shape rejections.'}], 'counterfactuals':cf,'shortcut_probes':probes,'delivery':{'stages_examined':['generator rejection/resampling','requested difficulty','normalization and validation','inventory and within-batch deduplication','fresh usable inventory eligibility','difficulty-first learner selection'], 'sample_refs':['finite-batch.json','packaging-results.json','delivery-sample/delivery.json','delivery-batch/delivery.json','selection-results.json','inventory-results.json'], 'result':'120/120 independent sample and 5/5 runner records survive actual shared filter. Decision coverage unchanged. Eligible stored records checked, easy-band selection does not condition on mathematical shape or wording. Exact future learner draw remains history/policy dependent.'}, 'limitations':['Finite probes do not establish absence of all shortcuts.','One radio and one where-blank in runner batch provide too few cases for subgroup-frequency inference; neither supports a repeated perfect conditional shortcut.','Source replay omission q-139628 is reported separately; counterfactuals assess current implemented families.','No stored defect demonstrated; affected-inventory.json is empty. Inventory generation metadata was not supplied, and was not invented.']}
save('pedagogical-variation.json',report)
print(json.dumps({'radio_probes':[{k:p[k] for k in ['cue','correct','total']} for p in probes[:5]],'coverage':[{t:len([r for r in load('samples.json') if typ(r['question'])==t]) for t in ['radio','where-dual-blank','let-dual-blank']}],'selection_easy_count':len(easy),'selection_reached':len(counts)}))
